    private readonly ComboBox _formatSection = new() { Name = "FormatSection", Width = 250, DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly ComboBox _formatRole = new() { Name = "FormatRole", Width = 130, DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly DataGridView _formatGrid = new() { Name = "FormatProperties", Dock = DockStyle.Fill, AllowUserToAddRows = false, RowHeadersVisible = false };
    private readonly DataGridView _furnitureGrid = new() { Name = "FormatFurniture", Dock = DockStyle.Fill, AllowUserToAddRows = false, RowHeadersVisible = false };
    private readonly DataGridView _objectsGrid = new() { Name = "FormatObjects", Dock = DockStyle.Fill, AllowUserToAddRows = false, RowHeadersVisible = false };
    private readonly RichTextBox _formatEvidence = new() { Name = "FormatEvidence", Dock = DockStyle.Fill, ReadOnly = true };
    private readonly Dictionary<string, JsonObject> _formatSpecs = new(StringComparer.Ordinal);
    private JsonObject? _formatSpec;
    private bool _bindingFormat;
    private sealed record SectionOption(string Section, string Position, string Label) { public override string ToString() => Label; }
    private static readonly (string Key, string Label, string Type)[] MainFormatFields = [("widthMm", "용지 너비(mm)", "number"), ("heightMm", "용지 높이(mm)", "number"), ("margins.left", "왼쪽 여백(mm)", "number"), ("margins.right", "오른쪽 여백(mm)", "number"), ("margins.top", "위 여백(mm)", "number"), ("margins.bottom", "아래 여백(mm)", "number"), ("margins.header", "머리말 여백(mm)", "number"), ("margins.footer", "꼬리말 여백(mm)", "number"), ("margins.gutter", "제본 여백(mm)", "number"), ("header", "새 머리말 글자", "text"), ("footer", "새 꼬리말 글자", "text"), ("headerVisible", "머리말 표시", "boolean"), ("footerVisible", "꼬리말 표시", "boolean"), ("pageNumberVisible", "동적 쪽번호 표시", "boolean"), ("pageNumberFormat", "쪽번호 형식(DIGIT/ROMAN_CAPITAL/ROMAN_SMALL)", "text"), ("pageNumberPosition", "쪽번호 위치(빈값=원본)", "optional"), ("applyBodyStyle", "본문 서식 적용", "boolean"), ("includeTables", "표 본문에도 적용", "boolean")];
    private static readonly (string Key, string Label, string Type)[] TypeFormatFields = [("fontFamily", "글꼴 이름", "text"), ("fontSizePt", "글자 크기(pt)", "number"), ("widthPercent", "장평(%)", "number"), ("spacingPercent", "자간(%)", "number"), ("lineSpacingPercent", "줄간격(%)", "number"), ("leftIndentMm", "왼쪽 들여쓰기(mm)", "number"), ("rightIndentMm", "오른쪽 들여쓰기(mm)", "number"), ("firstLineIndentMm", "첫 줄 들여쓰기/내어쓰기(mm)", "number"), ("spaceBeforePt", "문단 위 간격(pt)", "number"), ("spaceAfterPt", "문단 아래 간격(pt)", "number"), ("paragraphAlign", "정렬(LEFT/RIGHT/CENTER/JUSTIFY 등)", "optional"), ("keepWithNext", "다음 문단과 함께", "boolean"), ("keepLines", "문단을 한 쪽에 유지", "boolean"), ("widowOrphan", "외톨이줄 보호", "boolean")];
    private void BuildFormattingTab()
    {
        var tab = new TabPage("서식·개체 편집") { Name = "FormattingTab" }; var bar = new FlowLayoutPanel { Dock = DockStyle.Top, AutoSize = true }; bar.Controls.AddRange([_formatSection, _formatRole]); _formatRole.Items.AddRange(["body", "chapterTitle", "subheading", "tableCaption", "tableBody"]); _formatRole.SelectedItem = "body";
        foreach (var (name, label, action) in new (string, string, Func<Task>)[] { ("FormatOpen", "원본 서식 열기", () => OpenFormattingAsync()), ("FormatSectionOpen", "선택 구역 원본", () => OpenFormattingAsync(true)), ("FormatValidate", "서식 검사·저장", SaveFormattingAsync), ("FormatApply", "서식 반영 사본", ApplyFormattingAsync), ("FormatLinkPicture", "선택 근거 그림 연결", LinkFormattingPictureAsync), ("FormatUnlinkPicture", "그림 연결 해제", UnlinkFormattingPictureAsync) }) AddButton(bar, name, label, () => Run(action));
        _formatGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "key", HeaderText = "서식 위치", ReadOnly = true, Width = 200 }); _formatGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "label", HeaderText = "항목", ReadOnly = true, Width = 240 }); _formatGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = "value", HeaderText = "설정값(빈칸=원본/미지정)", AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill });
        foreach (var (key, label) in new[] { ("area", "영역"), ("slot", "원문 슬롯 ID"), ("text", "원문/변경 글자"), ("align", "정렬(빈값=원본)") }) _furnitureGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = key, HeaderText = label, ReadOnly = key is "area" or "slot", Width = key == "text" ? 350 : 180 });
        foreach (var (key, label) in new[] { ("id", "원본 개체 ID"), ("kind", "종류/영역"), ("positioning", "배치(source/page)"), ("x", "가로(mm)"), ("y", "세로(mm)"), ("picture", "교체 근거 ID") }) _objectsGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = key, HeaderText = label, ReadOnly = key is "id" or "kind" or "picture", Width = key is "id" or "picture" ? 210 : 130 });
        var pages = new TabControl { Dock = DockStyle.Fill }; foreach (var (label, control) in new (string, Control)[] { ("용지·문단·글자", _formatGrid), ("머리말·꼬리말", _furnitureGrid), ("표·그림·도형", _objectsGrid), ("원본 근거", _formatEvidence) }) { var page = new TabPage(label); page.Controls.Add(control); pages.TabPages.Add(page); }
        tab.Controls.Add(pages); tab.Controls.Add(bar); tab.Controls.Add(new Label { Dock = DockStyle.Bottom, Height = 38, Text = "원본 HWPX 구조를 보존한 별도 서식 후보입니다. 금회 초안/회사 완성본이 아니며 실제 한글 배치·글꼴은 별도 검증해야 합니다." }); _tabs.TabPages.Add(tab);
        _formatRole.SelectedIndexChanged += (_, _) => { if (!_bindingFormat && _formatSpec != null) { ReadFormattingEditor(); ShowFormattingEditor(); } };
        foreach (var grid in new[] { _formatGrid, _furnitureGrid, _objectsGrid }) grid.CellValueChanged += (_, _) => { if (!_bindingFormat) _dirty = true; };
    }
    private void ResetFormatting() { _formatSpecs.Clear(); _formatSpec = null; _formatSection.Items.Clear(); _formatGrid.Rows.Clear(); _furnitureGrid.Rows.Clear(); _objectsGrid.Rows.Clear(); }
    private void LoadFormattingState(JsonNode value) { foreach (var (key, item) in value["formatSpecs"]?.AsObject() ?? new JsonObject()) if (item is JsonObject spec) _formatSpecs[key] = (JsonObject)spec.DeepClone(); }
    private void SaveFormattingState(JsonObject value) { if (_formatSpec != null && _current != null && _formatSpec["sourceSha256"]?.ToString() == _current.Sha256) { ReadFormattingEditor(); _formatSpecs[FormatKey] = (JsonObject)_formatSpec.DeepClone(); } value["formatSpecs"] = System.Text.Json.JsonSerializer.SerializeToNode(_formatSpecs); }
    private void SelectFormattingSource() { _formatSpec = null; _formatSection.Items.Clear(); _formatGrid.Rows.Clear(); _furnitureGrid.Rows.Clear(); _objectsGrid.Rows.Clear(); _formatEvidence.Clear(); }
    private string FormatKey => _current!.Sha256 + ":" + (_formatSpec?["section"]?.ToString() ?? "") + ":" + (_formatSpec?["pagePropertyPosition"]?.ToString() ?? "");
    public async Task OpenFormattingAsync(bool selectedSection = false)
    {
        if (_bundle == null || _current == null) throw new InvalidOperationException(); var selection = _formatSection.SelectedItem as SectionOption; var parameters = new Dictionary<string, string> { ["filename"] = _current.Filename, ["action"] = "inspect" }; if (selectedSection && selection != null) { parameters["section"] = selection.Section; parameters["position"] = selection.Position; }
        var result = await Execute(Command("specification") with { Parameters = parameters }); _formatSpec = (JsonObject)result["spec"]!.DeepClone(); if (!selectedSection && _formatSpecs.TryGetValue(FormatKey, out var saved)) _formatSpec = (JsonObject)saved.DeepClone();
        _bindingFormat = true; _formatSection.Items.Clear(); foreach (var (item, index) in result["profile"]!["sections"]!.AsArray().Select((item, index) => (item!, index))) _formatSection.Items.Add(new SectionOption(item["section"]!.GetValue<string>(), item["position"]?.ToString() ?? "", $"구역 {index + 1} · {item["widthMm"]}×{item["heightMm"]}mm")); _formatSection.SelectedIndex = Math.Max(0, _formatSection.Items.Cast<SectionOption>().ToList().FindIndex(item => item.Section == _formatSpec["section"]?.ToString() && item.Position == (_formatSpec["pagePropertyPosition"]?.ToString() ?? ""))); _bindingFormat = false;
        _formatEvidence.Text = "현재 원본에서 추출한 실제 구역·글자/문단·머리말·개체 근거\n" + result.ToJsonString(DisplayJson); ShowFormattingEditor(); _tabs.SelectedTab = _tabs.TabPages["FormattingTab"];
    }
    private void ShowFormattingEditor()
    {
        if (_formatSpec == null) return; _bindingFormat = true; _formatGrid.Rows.Clear(); foreach (var field in MainFormatFields.Concat(TypeFormatFields)) { var path = TypeFormatFields.Any(item => item.Key == field.Key) && _formatRole.SelectedItem?.ToString() != "body" ? "roleStyles." + _formatRole.SelectedItem + "." + field.Key : field.Key; var value = GetFormatValue(path); var index = _formatGrid.Rows.Add(path, field.Label, value?.ToString() ?? ""); _formatGrid.Rows[index].Tag = field.Type; }
        _furnitureGrid.Rows.Clear(); foreach (var area in _bundle!["restoration"]?["furniture"]?.AsArray().Where(item => item?["section"]?.ToString() == _formatSpec["section"]?.ToString()) ?? []) foreach (var slot in area!["slots"]!.AsArray()) { var id = slot!["slotId"]!.GetValue<string>(); var index = _furnitureGrid.Rows.Add(area["id"]!.ToString(), id, _formatSpec["furnitureEdits"]?[id]?.ToString() ?? slot["text"]?.ToString() ?? "", _formatSpec["furnitureAlignments"]?[area["id"]!.ToString()]?.ToString() ?? ""); _furnitureGrid.Rows[index].Tag = slot["text"]?.ToString() ?? ""; }
        _objectsGrid.Rows.Clear(); foreach (var obj in _bundle!["restoration"]?["objects"]?.AsArray().Where(item => item?["section"]?.ToString() == _formatSpec["section"]?.ToString()) ?? []) { var id = obj!["id"]!.GetValue<string>(); var pos = _formatSpec["objectPositions"]?[id] ?? obj["position"]; var picture = _formatSpec["pictureReplacements"]?.AsArray().FirstOrDefault(item => item?["objectId"]?.ToString() == id)?["materialId"]?.ToString() ?? ""; var index = _objectsGrid.Rows.Add(id, obj["kind"] + "/" + obj["area"], pos?["positioning"]?.ToString() ?? "source", pos?["horizontalMm"]?.ToString() ?? "", pos?["verticalMm"]?.ToString() ?? "", picture); _objectsGrid.Rows[index].Tag = obj.DeepClone(); if (obj["position"] == null) foreach (var key in new[] { "positioning", "x", "y" }) _objectsGrid.Rows[index].Cells[key].ReadOnly = true; }
        _bindingFormat = false;
    }
    private JsonNode? GetFormatValue(string path) { JsonNode? node = _formatSpec; foreach (var key in path.Split('.')) node = node?[key]; return node; }
    private void PutFormatValue(string path, JsonNode? value) { var keys = path.Split('.'); var node = _formatSpec!; for (var i = 0; i < keys.Length - 1; i++) { node[keys[i]] ??= new JsonObject(); node = node[keys[i]]!.AsObject(); } if (value == null) node.Remove(keys[^1]); else node[keys[^1]] = value; }
    private static double NumberValue(string value) { if (!double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out var number) || !double.IsFinite(number)) throw new InvalidDataException(); return number; }
    private void ReadFormattingEditor()
    {
        if (_formatSpec == null) return; _formatGrid.EndEdit(); _furnitureGrid.EndEdit(); _objectsGrid.EndEdit(); foreach (DataGridViewRow row in _formatGrid.Rows) { var path = Convert.ToString(row.Cells["key"].Value)!; var value = Convert.ToString(row.Cells["value"].Value) ?? ""; var type = (string)row.Tag!; JsonNode? result = value == "" && type != "text" ? null : type == "number" ? JsonValue.Create(NumberValue(value)) : type == "boolean" ? JsonValue.Create(bool.Parse(value)) : JsonValue.Create(value); PutFormatValue(path, result); }
        var edits = new JsonObject(); var alignments = new JsonObject(); foreach (DataGridViewRow row in _furnitureGrid.Rows) { var id = Convert.ToString(row.Cells["slot"].Value)!; var text = Convert.ToString(row.Cells["text"].Value) ?? ""; if (text != (string)row.Tag!) edits[id] = text; var align = Convert.ToString(row.Cells["align"].Value) ?? ""; if (align != "") alignments[Convert.ToString(row.Cells["area"].Value)!] = align; }
        _formatSpec["furnitureEdits"] = edits; _formatSpec["furnitureAlignments"] = alignments;
        var positions = new JsonObject(); foreach (DataGridViewRow row in _objectsGrid.Rows) { var obj = (JsonNode)row.Tag!; if (obj["position"] == null) continue; var id = Convert.ToString(row.Cells["id"].Value)!; var mode = Convert.ToString(row.Cells["positioning"].Value) ?? "source"; var x = NumberValue(Convert.ToString(row.Cells["x"].Value) ?? "0"); var y = NumberValue(Convert.ToString(row.Cells["y"].Value) ?? "0"); if (mode != "source" || Math.Abs(x - (obj["position"]?["horizontalMm"]?.GetValue<double>() ?? 0)) > 0.00001 || Math.Abs(y - (obj["position"]?["verticalMm"]?.GetValue<double>() ?? 0)) > 0.00001) positions[id] = new JsonObject { ["positioning"] = mode, ["horizontalMm"] = x, ["verticalMm"] = y }; }
        _formatSpec["objectPositions"] = positions;
        if (_formatSpec["roleStyles"] is JsonObject roles) foreach (var key in roles.Where(item => item.Value is JsonObject value && value.Count == 0).Select(item => item.Key).ToArray()) roles.Remove(key);
    }
    public void SetFormattingProperty(string path, JsonNode? value) { if (_formatSpec == null) throw new InvalidOperationException(); ReadFormattingEditor(); PutFormatValue(path, value); ShowFormattingEditor(); _dirty = true; }
    private async Task<JsonNode> FormattingAction(string action) { await AuthorizeProfile(true, Token); ReadFormattingEditor(); var context = new JsonObject { ["spec"] = _formatSpec?.DeepClone() ?? throw new InvalidOperationException() }; var file = Path.Combine(_projectRoot, "format-" + Guid.NewGuid().ToString("N") + ".json"); await Atomic(file, context.ToJsonString(), Token); return await Execute(Command("specification", file) with { Parameters = new() { ["filename"] = _current!.Filename, ["action"] = action } }); }
    public async Task SaveFormattingAsync() { var result = await FormattingAction("validate"); _formatSpec = (JsonObject)result["spec"]!.DeepClone(); _formatSpecs[FormatKey] = (JsonObject)_formatSpec.DeepClone(); await SaveAsync(Token); Status("실제 원본 SHA·구역과 서식 범위를 검증해 설정을 저장했습니다. 원본 파일은 바뀌지 않습니다."); }
    public async Task ApplyFormattingAsync() { await SaveFormattingAsync(); var result = await FormattingAction("apply"); _summary.Text = "서식 편집 사본의 변경 근거\n" + result["review"]?.ToJsonString(DisplayJson); await SaveAsync(Token); Status("별도 서식 후보를 생성했습니다. 산출물 내려받기로 저장하고 실제 한글에서 배치·편집을 검증하세요. 금회 회사완성본이 아닙니다."); }
    private Task LinkFormattingPictureAsync() { if (_formatSpec == null || _objectsGrid.SelectedRows.Count != 1 || _evidence.SelectedItem is not EvidenceItem material || Path.GetExtension(material.Filename).ToLowerInvariant() is not (".png" or ".jpg" or ".jpeg" or ".webp")) throw new InvalidOperationException(); ReadFormattingEditor(); var row = _objectsGrid.SelectedRows[0]; var obj = (JsonNode)row.Tag!; if (obj["kind"]?.ToString() != "pic" || obj["image"] == null) throw new InvalidOperationException(); var id = obj["id"]!.ToString(); var replacements = new JsonArray((_formatSpec["pictureReplacements"]?.AsArray().Where(item => item?["objectId"]?.ToString() != id).Select(item => item!.DeepClone()) ?? []).ToArray()); replacements.Add(new JsonObject { ["objectId"] = id, ["materialId"] = material.Id, ["sha256"] = material.Sha256 }); _formatSpec["pictureReplacements"] = replacements; ShowFormattingEditor(); _dirty = true; return Task.CompletedTask; }
    private Task UnlinkFormattingPictureAsync() { if (_formatSpec == null || _objectsGrid.SelectedRows.Count != 1) throw new InvalidOperationException(); ReadFormattingEditor(); var id = Convert.ToString(_objectsGrid.SelectedRows[0].Cells["id"].Value)!; _formatSpec["pictureReplacements"] = new JsonArray((_formatSpec["pictureReplacements"]?.AsArray().Where(item => item?["objectId"]?.ToString() != id).Select(item => item!.DeepClone()) ?? []).ToArray()); ShowFormattingEditor(); _dirty = true; return Task.CompletedTask; }
}
